export function stableCandidateNoteId(articleId: number, note: Pick<Note, 'source_id' | 'value'> & { dossier?: { verbatim_sentence?: string; chunk_id?: number } }): string {
  const source = (note.source_id ?? '').trim();
  const value = (note.value ?? '').replace(/\s+/g, ' ').trim();
  const dossier = (note.dossier?.verbatim_sentence ?? '').replace(/\s+/g, ' ').trim();
  const digest = createHash('sha256')
    // Do not include chunk_id: live-update chunks are replaced on every
    // changed feed, so SQLite chunk IDs are not stable across reprocessing.
    .update(`${articleId}\n${source}\n${value}\n${dossier}`)
    .digest('hex')
    .slice(0, 12);
  return `a${articleId}-c${digest}`;
}

