/**
 * Article-dedup step (T23/T24, ADR-0027).
 *
 * Sits between ingest and chunk. Reduces extraction cost by collapsing
 * exact-duplicate articles (canonical URL or content_hash) and, when L2 is
 * enabled, syndicated near-duplicates (title+body MinHash). Survivors carry
 * a `publisher_aliases[]` field that downstream consumers can show but that
 * MUST NOT bump `independence_count` (the verification corroboration
 * signal).
 *
 * No LLM. No lint retry.
 */

import type { Logger } from 'shared/logger.js';
import type { FeedArticle } from '../../../services/articles/index.js';
import {
  dedupeArticles,
  type ArticleDedupArtifact,
  type ArticleDedupOptions,
} from '../../../services/articles/article-dedup.js';

export interface ArticleDedupInput {
  articles: FeedArticle[];
  options?: ArticleDedupOptions;
}

export async function runArticleDedupStep(input: ArticleDedupInput, log: Logger): Promise<ArticleDedupArtifact> {
  const t0 = performance.now();
  log.info('article_dedup.start', `Article-dedup: ${input.articles.length} article(s) in`);
  const result = dedupeArticles(input.articles, input.options ?? {});
  const dropped = input.articles.length - result.articles.length;
  const groupsByRelation = {
    exact_duplicate:      result.groups.filter((g) => g.relation === 'exact_duplicate').length,
    syndicated_duplicate: result.groups.filter((g) => g.relation === 'syndicated_duplicate').length,
    near_duplicate:       result.groups.filter((g) => g.relation === 'near_duplicate').length,
    unique:               result.groups.filter((g) => g.relation === 'unique').length,
  };
  const ms = Math.round(performance.now() - t0);
  log.info('article_dedup.complete',
    `Article-dedup: ${input.articles.length} → ${result.articles.length} survivor(s), ${dropped} dropped, ` +
    `exact=${groupsByRelation.exact_duplicate}, syndicated=${groupsByRelation.syndicated_duplicate}, ` +
    `unique=${groupsByRelation.unique} (${ms}ms)`);
  return result;
}

