export function loadFixtureArticles(articlesPath: string): FeedArticle[] {
  const raw = JSON.parse(readFileSync(articlesPath, 'utf-8')) as FeedArticle[];
  if (!Array.isArray(raw)) {
    throw new Error(`fixture articles: expected JSON array at ${articlesPath}`);
